import{_ as i,l as o,o as e,c as n,v as t,p as s,x as l,d,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"弃权与校准拒答","description":"","frontmatter":{"title":"弃权与校准拒答","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/abstention-calibrated-refusal.md","filePath":"llm/abstention-calibrated-refusal.md","lastUpdated":1789023840000}'),p={name:"llm/abstention-calibrated-refusal.md"};function c(A,a,m,_,u,f){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="弃权与校准拒答" tabindex="-1">弃权与校准拒答 <a class="header-anchor" href="#弃权与校准拒答" aria-label="Permalink to &quot;弃权与校准拒答&quot;">​</a></h1><div class="epigraph"><p>会说「我不知道」并且知道何时说，比把每个空档填满更接近诚实。校准是频率，不是礼貌。</p><footer>—— 对照 Kadavath 等对语言模型自知的讨论；[过拒绝](/llm/over-refusal) 是另一方向的误差</footer></div><p><a href="/llm/hallucination-taxonomy">上一课</a>把事实错误单列。本课补动作：弃权（abstention）与校准拒答——在不确定或无来源时不编。缺口是：拒绝训练容易把「无害拒答」泛化成过拒绝，而「必须有帮助」又把空档填成幻觉。后课记忆化不再处理校准，只处理训练数据复现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/over-refusal">过拒绝</a> 是安全轴上的假阳性。本课是知识轴上的假阳性/假阴性：该弃权时硬答（幻觉），该答时弃权（无用）。两者不能用同一条拒答率优化。校准要求：在「我有把握」的声明下，正确频率接近声明的置信度，见 <a href="/llm/calibration-ece">ECE</a>。</p><p>产品还要把「无工具时弃权」与「有检索时必须答」分开，否则 RAG 会学会永远不敢用检索到的段落。</p><p><span class="marginnote">口头「我不确定」若后面仍给一个确定事实，是风格不是弃权。弃权必须改变动作：不给可核验命题，或明确标成猜测。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>持有集两列：必须答（简单事实、检索已命中）；必须弃权（过时、无源、冲突源）。优化与评测都报双列，禁止合成一个「安全分数」。动作空间：短拒答、给出检索、给出置信区间、要求澄清。不要把长道歉当弃权。</p>',9)),(e(),s(h,null,{default:l(()=>[E(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%97%AE%E9%A2%98%22%5D%20--%3E%20U%5B%22%E4%B8%8D%E7%A1%AE%E5%AE%9A%EF%BC%9F%22%5D%0A%20%20U%20--%3E%7C%22%E5%90%A6%22%7C%20A%5B%22%E4%BD%9C%E7%AD%94%22%5D%0A%20%20U%20--%3E%7C%22%E6%98%AF%22%7C%20AB%5B%22%E5%BC%83%E6%9D%83%20%2F%20%E6%A3%80%E7%B4%A2%20%2F%20%E6%BE%84%E6%B8%85%22%5D%0A%20%20AB%20--%3E%20OV%5B%22%E8%BF%87%E6%8B%92%E7%BB%9D%E9%A3%8E%E9%99%A9%22%5D%0A%20%20A%20--%3E%20HAL%5B%22%E5%B9%BB%E8%A7%89%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RLHF 的「有帮助」头推动填空；「无害」头推动拒答。知识不确定性若没有自己的头，就会被两头夹成随机礼貌。可验证任务上可以用「答错惩罚大于弃权」塑形；开放事实只能靠检索门与校准数据。口头置信度往往过满，因为训练语料里少有「我不知道」的高质示范。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理有害请求的拒答策略（那是安全分类器与宪法）。下一课记忆化问的是「答对了但是否在背训练样本」，与不确定弃权正交：背得出来仍可能侵权。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>弃权是知识轴上的动作，必须与安全拒答分列评测。</li><li>校准看频率，不看套话。</li><li>「有帮助」与「无害」两头夹不住不确定性，需要单独持有集。</li><li>出处：Kadavath 等；过拒绝课。</li></ul>',6))])}const C=i(p,[["render",c]]);export{b as __pageData,C as default};
